"""Synthetic contract tests: no production artwork is generated by these fixtures."""
import sys
import tempfile
import unittest
from pathlib import Path

from PIL import Image, ImageDraw

sys.path.insert(0, str(Path(__file__).resolve().parents[1] / "scripts"))
from validate_toxic_environment import GROUND, PROPS, asset_names, validate


class EnvironmentPreflightTests(unittest.TestCase):
    def test_world_contracts_are_distinct_and_backward_compatible(self):
        self.assertEqual(asset_names(2), (GROUND, PROPS))
        sets = [set(sum(asset_names(world), [])) for world in (2, 3, 4)]
        self.assertTrue(all(len(names) == 10 for names in sets))
        self.assertEqual(len(set.union(*sets)), 30)

    def test_complete_and_negative_controls_each_world(self):
        for world in (2, 3, 4):
            with self.subTest(world=world), tempfile.TemporaryDirectory() as temp:
                root = Path(temp)
                ground, props = asset_names(world)
                floor = Image.new("RGBA", (1024, 1024), (31, 40, 50, 255))
                for name in ground:
                    floor.save(root / name)
                prop = Image.new("RGBA", (512, 512))
                ImageDraw.Draw(prop).rectangle((128, 100, 383, 479), fill=(100, 120, 140, 255))
                for name in props:
                    prop.save(root / name)
                report = validate(root, world)
                self.assertTrue(report["technical_complete"], report)
                self.assertFalse(report["visual_approved"])
                self.assertEqual(report["edge_comparisons"], 32)
                # A wrong-world or missing asset cannot pass the strict gate.
                (root / props[0]).unlink()
                self.assertFalse(validate(root, world)["technical_complete"])
                prop.save(root / props[0])
                # A single mismatched edge pixel must be caught.
                bad = floor.copy()
                bad.putpixel((0, 500), (255, 0, 0, 255))
                bad.save(root / ground[0])
                self.assertTrue(any("edge mismatch" in e for e in validate(root, world)["errors"]))
                floor.save(root / ground[0])
                # A transparent floor must fail independently of seam checks.
                bad.putpixel((500, 500), (0, 0, 0, 0))
                bad.save(root / ground[0])
                self.assertTrue(any("ground must be opaque" in e for e in validate(root, world)["errors"]))
                floor.save(root / ground[0])
                # A misregistered prop may not be accepted.
                bad_prop = Image.new("RGBA", (512, 512))
                ImageDraw.Draw(bad_prop).rectangle((128, 100, 383, 440), fill=(100, 120, 140, 255))
                bad_prop.save(root / props[0])
                self.assertTrue(any("visible ground contact" in e for e in validate(root, world)["errors"]))


if __name__ == "__main__":
    unittest.main()
